code_snippets.parse_list:
def parse_list(self, response):
    items = response.css('ul li')
    for item in items:
        detail_url = item.css('a::attr(href)').get()
        if detail_url and detail_url.startswith('/content/'):
            yield response.follow(detail_url, callback=self.parse_detail)

code_snippets.parse_detail:
def parse_detail(self, response):
    yield {
        'title': response.css('h1::text').get(),
        'author': response.css('div.author::text').get(),
        'abstract': response.css('div.abstract::text').get(),
        'publication_date': response.css('span.pub-date::text').get(),
        'pdf_url': response.css('a[href$=".pdf"]::attr(href)').get(),
        'supplementary_urls': response.css('a.supplementary::attr(href)').getall()
    }
